mapper.select:
SELECT id, tag_group_id, name, sort_order, init_regi_pic, init_regi_dttm, final_rvis_pic, final_rvis_dttm FROM tag
WHERE tag_group_id = #{tagGroupId}
ORDER BY sort_order ASC NULLS LAST, id ASC

SELECT EXISTS (
    SELECT 1 FROM tag WHERE tag_group_id = #{tagGroupId}
)

